"""Summary statistics for the reporting CLI."""

import math


def percentile(values, p):
    """Nearest-rank percentile of `values` for percentile `p` in [0, 100].

    The value at 1-based rank ``ceil(p / 100 * n)`` is returned.
    ``p=0`` returns the minimum and ``p=100`` the maximum.
    """
    if p < 0 or p > 100:
        raise ValueError("percentile must be between 0 and 100")

    ordered = sorted(values)
    n = len(ordered)
    if n == 0:
        raise ValueError("percentile of empty sequence")

    # Whole-number percentiles use integer arithmetic so the rank stays exact
    # for large samples. Other percentiles use the same ceiling definition.
    if _is_whole_number(p):
        rank = (int(p) * n + 99) // 100
    else:
        rank = math.ceil(p / 100 * n)
    if rank < 1:
        rank = 1
    elif rank > n:
        rank = n
    return ordered[rank - 1]


def _is_whole_number(p):
    """True when `p` is an integral number, so the rank can be computed exactly."""
    if isinstance(p, bool) or isinstance(p, int):
        return isinstance(p, int) and not isinstance(p, bool)
    if isinstance(p, float):
        return p.is_integer()
    try:
        return float(p).is_integer() and int(p) == p
    except (TypeError, ValueError, OverflowError):
        return False


def old_percentile(values, p):
    """Legacy alias for :func:`percentile`, retained for the v1 report format."""
    return percentile(values, p)

